// Generated files are committed; Cloudflare Pages still serves a plain static site.
// Install build-only dependencies into output/audit-tools/build before running.
import fs from 'node:fs/promises';
import path from 'node:path';
import {createRequire} from 'node:module';
import {pathToFileURL} from 'node:url';
const require=createRequire(import.meta.url);
const deps=[path.resolve('output/audit-tools/build')];
const CleanCSS=require(require.resolve('clean-css',{paths:deps}));
const {minify}=await import(pathToFileURL(require.resolve('terser',{paths:deps})));
const cssFiles=['styles.css','jubilee.css','home.css','heavenly.css','account.css'];
const jsFiles=['script.js','account.js','jubilee.js','home.js','heavenly.js'];
const css=new CleanCSS({rebase:false,level:1}).minify((await Promise.all(cssFiles.map(p=>fs.readFile(p,'utf8')))).join('\n'));
if(css.errors.length)throw Error(css.errors.join('\n'));
const js=await minify(Object.fromEntries(await Promise.all(jsFiles.map(async p=>[p,await fs.readFile(p,'utf8')]))),{mangle:{toplevel:false},compress:{toplevel:false},format:{comments:false}});
await fs.writeFile('homepage.min.css','/* Generated by tools/build-homepage.mjs; edit the source CSS files. */\n'+css.styles+'\n');
await fs.writeFile('homepage.min.js','/* Generated by tools/build-homepage.mjs; edit the source JS files. */\n'+js.code+'\n');
console.log('Built homepage.min.css',css.styles.length,'characters; homepage.min.js',js.code.length,'characters');
